#!/usr/bin/env node
// Generates the typed Rust API surface of crates/types (crate better-iam-types) from spec/api/openapi.json and
// spec/api/routes.json.
//
//   node scripts/spec/gen-rust-types.mjs             regenerate crates/types/src/{schemas.rs,routes.rs,api/*.rs}
//   node scripts/spec/gen-rust-types.mjs --out DIR   write the generated files under DIR/src instead
//   (--spec DIR and --core DIR override the spec/ and crates/core/src directories that are read)
//
// Output is deterministic: it depends only on the two spec files and on the serde-capable public types declared in
// crates/core/src, and every file is passed through rustfmt (found on PATH or in ~/.cargo/bin). The hand-written
// files of the crate (lib.rs, runtime.rs, macros.rs) are never touched. scripts/spec/check-generated.mjs regenerates
// into a temporary directory and fails when the checked-in files differ.
//
// Mapping:
//
// - Every component schema becomes one Rust item of the same name in `schemas`, except the names better-iam-core
//   already declares with a serde form (Tenant, Identity, AuditEvent, Decision, ...): those are re-exported from
//   the core crate.
// - Every RPC route of routes.json becomes, in `api::<group>`, `<Method>Input` (the request body), `<Method>Output`
//   (the `data` of the answer) and a marker `<Method>` implementing `routes::Operation`. The special routes
//   authorize, authorizeMany and listAccessible (`api::operations`) are built from the TypeScript operation
//   signatures and the HTTP dispatch in packages/server/src/http.ts. `routes::ROUTES` is the operation table.
// - Objects become structs (members in schema order, explicit JSON names). Required members are plain fields;
//   optional ones are `Option<T>` left out when `None`; nullable ones `Option<T>` written as `null`; optional and
//   nullable ones `Option<Option<T>>` (absent, null and a value stay distinct). Members of any type are
//   `Option<serde_json::Value>` where `Some(Value::Null)` is an explicit null. Objects that allow other members keep
//   them in a flattened `extra` map.
// - Closed string enums become Rust enums; open ones (`'a' | (string & {})`) a string newtype with constants.
//   `true | false` is bool; numbers are f64 (JavaScript numbers).
// - Unions whose variants are all inline objects with a distinct string constant in a common required member become
//   internally tagged enums (`#[serde(tag = "...")]`). Other unions are untagged enums that pick the first variant
//   whose JSON shape matches (runtime::untagged).
// - Free-form objects are serde_json::Map (property order kept); unknown values serde_json::Value. Recursive types
//   are boxed where needed.
import { spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');
const args = process.argv.slice(2);
const option = (name, fallback) => {
  const index = args.indexOf(name);
  return index >= 0 ? resolve(args[index + 1]) : fallback;
};
const outDir = option('--out', join(root, 'crates', 'types'));
const specDir = option('--spec', join(root, 'spec'));
const coreDir = option('--core', join(root, 'crates', 'core', 'src'));

const GENERATOR = 'scripts/spec/gen-rust-types.mjs';
const HEADER = `// @generated by ${GENERATOR} from spec/api/openapi.json and spec/api/routes.json. Do not edit.`;

const openapi = JSON.parse(readFileSync(join(specDir, 'api', 'openapi.json'), 'utf8'));
const routes = JSON.parse(readFileSync(join(specDir, 'api', 'routes.json'), 'utf8'));
const schemas = openapi.components.schemas;
const warnings = [];

// --- corrections to openapi.json ------------------------------------------------------------------------------------
//
// Places where the JSON the TypeScript server sends differs from what openapi.json declares, found by the round trip
// of the recorded traces (crates/types/tests/round_trip.rs). Each is applied to the in-memory document before the
// types are generated, and a correction that no longer applies is reported, so it can be dropped once the source is
// fixed.
//
// - `optional`: members declared `x: T | undefined` (often inferred from an object literal such as
//   `{ verifiedAt: record.verifiedAt }`). JSON leaves undefined members out, but the docs generator
//   (apps/docs/scripts/generate.mjs, describeObject) lists every property without the optional flag as required.
// - `add`: members the TypeScript passes through or returns that its declared type leaves out (added as optional).
const OVERRIDES = [
  { route: 'credentials/create', side: 'output', path: [], optional: ['name'] },
  { route: 'compliance/listControls', side: 'output', path: ['items'], optional: ['latest'] },
  { route: 'domains/add', side: 'output', path: [], optional: ['verifiedAt', 'lastCheckedAt'] },
  {
    route: 'domains/verify',
    side: 'output',
    path: ['properties', 'domain'],
    optional: ['verifiedAt', 'lastCheckedAt'],
  },
  {
    route: 'webhooks/listDeliveries',
    side: 'output',
    path: ['items'],
    optional: ['eventId', 'deliveredAt', 'failedAt', 'lastError'],
  },
  { route: 'roleMining/apply', side: 'output', path: [], optional: ['createdBindingId'] },
  // http.ts: `auth/confirmMfa` uses body.credential only for a sign-in challenge, else the request credential.
  { route: 'auth/confirmMfa', side: 'input', path: [], optional: ['credential'] },
  // billing.ts declares `{ tenantId; period?; groupBy? } & SpendFilters` but passes the whole SpendQuery on.
  {
    route: 'billing/spend',
    side: 'input',
    path: ['allOf', 0],
    add: { shareUnattributed: { type: 'boolean' } },
  },
  // tenants.ts writes `creatorId` on owner invitations (OwnerInvitation does not declare it) and returns the record.
  {
    route: 'tenants/listInvitations',
    side: 'output',
    path: ['items'],
    add: { creatorId: { type: 'string' } },
  },
  {
    route: 'tenants/revokeInvitation',
    side: 'output',
    path: [],
    add: { creatorId: { type: 'string' } },
  },
];

for (const override of OVERRIDES) {
  const where = `correction ${override.route} ${override.side} ${override.path.join('.') || '(top)'}`;
  const post = openapi.paths[`/${override.route}`]?.post;
  if (!post) throw new Error(`${where}: no such route in openapi.json`);
  let node =
    override.side === 'input'
      ? post.requestBody?.content?.['application/json']?.schema
      : post.responses?.['200']?.content?.['application/json']?.schema?.properties?.data;
  for (const key of override.path) node = node?.[key];
  if (!node || node.type !== 'object' || !node.properties)
    throw new Error(`${where}: not an object schema`);
  for (const name of override.optional ?? []) {
    if (!node.properties[name]) throw new Error(`${where}: no member ${name}`);
    if (!node.required?.includes(name))
      warnings.push(`${where}: ${name} is already optional; drop the correction`);
    else node.required = node.required.filter((item) => item !== name);
  }
  for (const [name, schema] of Object.entries(override.add ?? {})) {
    if (node.properties[name])
      warnings.push(`${where}: ${name} is declared now; drop the correction`);
    else node.properties[name] = schema;
  }
}

// --- better-iam-core types ------------------------------------------------------------------------------------------

/**
 * Public structs and enums of better-iam-core that have a serde form (derived or implemented by hand) and are
 * reachable as `better_iam_core::Name` (declared in lib.rs or in a module lib.rs re-exports with `pub use m::*`).
 */
function readCoreTypes(dir) {
  const lib = readFileSync(join(dir, 'lib.rs'), 'utf8');
  const globbed = new Set([...lib.matchAll(/^pub use (\w+)::\*;/gm)].map((match) => match[1]));
  const types = new Set();
  const all = new Set();
  for (const file of readdirSync(dir)
    .filter((name) => name.endsWith('.rs'))
    .sort()) {
    const module = file.slice(0, -3);
    if (module !== 'lib' && !globbed.has(module)) continue;
    const text = readFileSync(join(dir, file), 'utf8');
    const manualSer = new Set(
      [...text.matchAll(/^impl Serialize for (\w+)/gm)].map((match) => match[1]),
    );
    const manualDe = new Set(
      [...text.matchAll(/^impl<'de> Deserialize<'de> for (\w+)/gm)].map((match) => match[1]),
    );
    // A declaration with the attribute lines above it.
    for (const match of text.matchAll(
      /((?:^[ \t]*#\[[^\n]*\n|^[ \t]*\/\/\/[^\n]*\n)*)^pub (?:struct|enum) (\w+)/gm,
    )) {
      const [, attributes, name] = match;
      all.add(name);
      const derives = [...attributes.matchAll(/#\[derive\(([^)]*)\)\]/g)]
        .map((derive) => derive[1])
        .join(',');
      const ser = /\bSerialize\b/.test(derives) || manualSer.has(name);
      const de = /\bDeserialize\b/.test(derives) || manualDe.has(name);
      if (ser && de) types.add(name);
    }
  }
  return { types, all };
}

const core = readCoreTypes(coreDir);
const coreMapped = new Set(Object.keys(schemas).filter((name) => core.types.has(name)));
const coreWithoutSerde = Object.keys(schemas).filter(
  (name) => core.all.has(name) && !core.types.has(name),
);

// --- schema normalization -------------------------------------------------------------------------------------------
//
// IR nodes: { k: 'any' | 'null' | 'ref' | 'string' | 'number' | 'bool' | 'array' | 'tuple' | 'map' | 'freeobject' |
// 'object' | 'union', nullable? }. Scalars carry `open` (any value of the type) and `consts` (the listed values; with
// open, only the known ones). Objects carry `props` [{ name, ir, required, description }] and `extra` (the IR of
// other members, null when the object is closed).

const refName = (ref) => {
  const prefix = '#/components/schemas/';
  if (!ref.startsWith(prefix)) throw new Error(`unsupported $ref ${ref}`);
  const name = ref.slice(prefix.length);
  if (!schemas[name]) throw new Error(`dangling $ref ${ref}`);
  return name;
};

const componentIR = new Map();
function comp(name) {
  if (!componentIR.has(name)) {
    componentIR.set(name, undefined);
    componentIR.set(name, norm(schemas[name]));
  }
  const ir = componentIR.get(name);
  if (!ir) throw new Error(`cyclic allOf through components/schemas/${name}`);
  return ir;
}

/** Follows references; the result is nullable when the reference chain or the target is. */
function deref(ir) {
  let current = ir;
  let nullable = !!ir.nullable;
  for (let depth = 0; current.k === 'ref'; depth++) {
    if (depth > 64) throw new Error(`$ref loop at ${ir.name}`);
    current = comp(current.name);
    nullable ||= !!current.nullable;
  }
  return nullable && !current.nullable ? { ...current, nullable } : current;
}

function constIR(value) {
  if (value === null) return { k: 'null' };
  if (typeof value === 'string') return { k: 'string', open: false, consts: [value] };
  if (typeof value === 'number') return { k: 'number', open: false, consts: [value] };
  if (typeof value === 'boolean') return { k: 'bool', open: false, consts: [value] };
  return { k: 'any' };
}

function norm(schema) {
  if (schema === undefined || schema === true || schema === null) return { k: 'any' };
  if (schema === false) throw new Error('the false schema is not supported');
  if (schema.$ref) return { k: 'ref', name: refName(schema.$ref) };
  if (schema.anyOf) return normAnyOf(schema.anyOf.map(norm));
  if (schema.oneOf) return normAnyOf(schema.oneOf.map(norm));
  if (schema.allOf) return normAllOf(schema.allOf.map(norm));
  if ('const' in schema) return constIR(schema.const);
  if (schema.enum) return normAnyOf(schema.enum.map(constIR));
  if (Array.isArray(schema.type))
    return normAnyOf(schema.type.map((type) => norm({ ...schema, type })));
  switch (schema.type) {
    case 'string':
      return { k: 'string', open: true };
    case 'number':
    case 'integer':
      return { k: 'number', open: true };
    case 'boolean':
      return { k: 'bool', open: true };
    case 'null':
      return { k: 'null' };
    case 'array':
      if (schema.prefixItems) return { k: 'tuple', items: schema.prefixItems.map(norm) };
      return { k: 'array', items: norm(schema.items) };
    case 'object':
      return normObject(schema);
    case undefined:
      return { k: 'any' };
    default:
      throw new Error(`unsupported schema type ${JSON.stringify(schema.type)}`);
  }
}

function normObject(schema) {
  const required = new Set(schema.required ?? []);
  const props = Object.entries(schema.properties ?? {}).map(([name, propSchema]) => ({
    name,
    ir: norm(propSchema),
    required: required.has(name),
    description: propSchema?.description,
  }));
  const additional = schema.additionalProperties;
  let extra;
  if (additional === false) extra = null;
  // Without additionalProperties, a schema with members is the closed shape the docs generator writes for envelopes;
  // one without members is TypeScript's `object` / `{}`: any members.
  else if (additional === undefined) extra = props.length ? null : { k: 'any' };
  else if (additional === true) extra = { k: 'any' };
  else extra = norm(additional);
  if (!props.length) {
    if (!extra) return { k: 'object', props: [], extra: null };
    return extra.k === 'any' ? { k: 'freeobject' } : { k: 'map', value: extra };
  }
  return { k: 'object', props, extra };
}

function normAnyOf(list) {
  let nullable = false;
  const flat = [];
  const push = (variant) => {
    if (variant.k === 'null') {
      nullable = true;
      return;
    }
    let v = variant;
    if (v.nullable) {
      nullable = true;
      v = { ...v, nullable: false };
    }
    if (v.k === 'union') {
      v.variants.forEach(push);
      return;
    }
    flat.push(v);
  };
  list.forEach(push);
  if (flat.some((v) => v.k === 'any')) return { k: 'any' };
  const out = [];
  const scalars = {};
  for (const v of flat) {
    if (v.k === 'string' || v.k === 'number' || v.k === 'bool') {
      const previous = scalars[v.k];
      if (!previous) {
        const copy = { k: v.k, open: v.open };
        if (v.consts) copy.consts = [...v.consts];
        scalars[v.k] = copy;
        out.push(copy);
      } else {
        previous.open = previous.open || v.open;
        for (const value of v.consts ?? []) {
          previous.consts ??= [];
          if (!previous.consts.includes(value)) previous.consts.push(value);
        }
      }
    } else out.push(v);
  }
  const bool = scalars.bool;
  if (bool?.consts?.includes(true) && bool.consts.includes(false)) {
    bool.open = true;
    delete bool.consts;
  }
  if (bool?.open) delete bool.consts;
  if (!out.length) return nullable ? { k: 'null' } : { k: 'any' };
  if (out.length === 1) return nullable ? { ...out[0], nullable: true } : out[0];
  return { k: 'union', variants: out, nullable };
}

const isEmptyObject = (ir) => ir.k === 'freeobject' || (ir.k === 'object' && !ir.props.length);

function normAllOf(parts) {
  const resolved = parts.map((part) => (part.k === 'ref' ? deref(part) : part));
  // TypeScript's `string & {}` (a string that keeps editor completions for the listed literals).
  const strings = resolved.filter((part) => part.k === 'string');
  if (strings.length && resolved.every((part) => part.k === 'string' || isEmptyObject(part)))
    return { ...strings[0], open: true };
  // An intersection with a union distributes over its variants.
  const unionIndex = resolved.findIndex((part) => part.k === 'union');
  if (unionIndex >= 0) {
    const union = resolved[unionIndex];
    const merged = normAnyOf(
      union.variants.map((variant) =>
        normAllOf([...resolved.slice(0, unionIndex), variant, ...resolved.slice(unionIndex + 1)]),
      ),
    );
    return union.nullable ? { ...merged, nullable: true } : merged;
  }
  // `Omit<T, 'k'> & { k?: string }[]`: TypeScript reads it as `Omit<T, 'k'> & ({ k?: string }[])`, but the server
  // treats the value as an array of objects with the members of both parts (billing.recordMany's `events`).
  const arrays = resolved.filter((part) => part.k === 'array');
  if (arrays.length) {
    const objects = resolved.filter((part) => part.k !== 'array');
    return {
      k: 'array',
      items: mergeObjects([...objects, ...arrays.map((array) => deref(array.items))]),
    };
  }
  return mergeObjects(resolved);
}

function mergeObjects(list) {
  const props = [];
  const index = new Map();
  let extra = null;
  for (const part of list.map((item) => (item.k === 'ref' ? deref(item) : item))) {
    if (part.k === 'freeobject') {
      extra ??= { k: 'any' };
      continue;
    }
    if (part.k === 'map') {
      extra ??= part.value;
      continue;
    }
    if (part.k !== 'object') throw new Error(`allOf over a ${part.k} schema is not supported`);
    for (const prop of part.props) {
      if (index.has(prop.name)) {
        const previous = props[index.get(prop.name)];
        previous.required ||= prop.required;
        if (previous.ir.k === 'any') previous.ir = prop.ir;
        else if (JSON.stringify(deref(previous.ir)) !== JSON.stringify(deref(prop.ir)))
          warnings.push(
            `allOf: member "${prop.name}" is declared twice with different types; the first is kept`,
          );
        continue;
      }
      index.set(prop.name, props.length);
      props.push({ ...prop });
    }
    if (part.extra) extra ??= part.extra;
  }
  if (!props.length) {
    if (!extra) return { k: 'object', props: [], extra: null };
    return extra.k === 'any' ? { k: 'freeobject' } : { k: 'map', value: extra };
  }
  return { k: 'object', props, extra };
}

const strip = (ir) => (ir.nullable ? { ...ir, nullable: false } : ir);

// --- naming ---------------------------------------------------------------------------------------------------------

function words(text) {
  return String(text)
    .replace(/[^A-Za-z0-9]+/g, ' ')
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1 $2')
    .replace(/([A-Za-z])([0-9])/g, '$1 $2')
    .trim()
    .split(/\s+/)
    .filter(Boolean);
}

const capitalize = (word) => word[0].toUpperCase() + word.slice(1).toLowerCase();

/** PascalCase in Rust style (`ID` → `Id`). */
function pascal(text) {
  const name = words(text).map(capitalize).join('');
  if (!name) return '';
  return /^[0-9]/.test(name) ? `N${name}` : name;
}

const snake = (text) =>
  words(text)
    .map((word) => word.toLowerCase())
    .join('_');

const screaming = (text) => snake(text).toUpperCase();

const STRICT_KEYWORDS = new Set(
  (
    'as break const continue crate else enum extern false fn for if impl in let loop match mod move mut pub ref ' +
    'return self Self static struct super trait true type unsafe use where while async await dyn abstract become ' +
    'box do final macro override priv typeof unsized virtual yield try gen'
  ).split(' '),
);
const NOT_RAW = new Set(['crate', 'self', 'Self', 'super', '_']);

function rustIdent(name) {
  if (!STRICT_KEYWORDS.has(name) && name !== '_') return name;
  return NOT_RAW.has(name) ? `${name}_` : `r#${name}`;
}

/** serde's `rename_all = "camelCase"` applied to a field identifier. */
function serdeCamel(ident) {
  const field = ident.startsWith('r#') ? ident.slice(2) : ident;
  let pascalName = '';
  let upper = true;
  for (const ch of field) {
    if (ch === '_') upper = true;
    else if (upper) {
      pascalName += ch.toUpperCase();
      upper = false;
    } else pascalName += ch;
  }
  return pascalName.slice(0, 1).toLowerCase() + pascalName.slice(1);
}

// Names that generated code uses unqualified (std prelude, the serde derive helpers) or that the crate root and the
// generated modules declare; a generated type never takes them.
const RESERVED = new Set([
  'Option',
  'Some',
  'None',
  'Result',
  'Ok',
  'Err',
  'Vec',
  'String',
  'Box',
  'Default',
  'Self',
]);

for (const name of Object.keys(schemas)) {
  if (!/^[A-Z][A-Za-z0-9]*$/.test(name))
    throw new Error(`schema name ${name} is not a Rust type name`);
  if (RESERVED.has(name)) throw new Error(`schema name ${name} is reserved in the generated code`);
}

// --- modules and declarations ---------------------------------------------------------------------------------------
//
// TypeRefs: { t: 'value' } (serde_json::Value), { t: 'object' } (serde_json::Map), { t: 'string' | 'f64' | 'bool' },
// { t: 'named', mod, name, core? }, { t: 'vec' | 'map' | 'opt', of }, { t: 'tuple', items }.
// Declarations: { kind: 'struct' | 'enum' | 'open' | 'tagged' | 'untagged' | 'alias', mod, name, doc, ... }.

class Module {
  constructor(path, file, doc) {
    this.path = path; // Rust path below the crate: 'schemas' or 'api::access_paths'
    this.file = file; // file under src/
    this.doc = doc;
    this.used = new Set(RESERVED);
    this.decls = [];
    this.items = []; // extra rendered items (markers), in order
  }
  claim(name, what) {
    let candidate = name;
    for (let suffix = 2; this.used.has(candidate); suffix++) candidate = `${name}${suffix}`;
    if (candidate !== name && what)
      warnings.push(`${this.path}: ${what} ${name} is taken, using ${candidate}`);
    this.used.add(candidate);
    return candidate;
  }
}

const declsByKey = new Map(); // `${mod}::${name}` → decl
const keyOf = (mod, name) => `${mod}::${name}`;

function addDecl(module, decl) {
  decl.mod = module.path;
  module.decls.push(decl);
  declsByKey.set(keyOf(module.path, decl.name), decl);
  return decl;
}

const schemasModule = new Module('schemas', 'schemas.rs', null);
for (const name of Object.keys(schemas)) schemasModule.used.add(name);

const VALUE = { t: 'value' };

/** The TypeRef of an IR node, ignoring its own nullability; declares named types in `module` under `context`. */
function typeRef(ir, context, module) {
  switch (ir.k) {
    case 'any':
    case 'null':
      return VALUE;
    case 'ref':
      return { t: 'named', mod: 'schemas', name: ir.name, core: coreMapped.has(ir.name) };
    case 'string':
      if (ir.consts) return declareEnum(module.claim(context, 'enum'), ir, module, null);
      return { t: 'string' };
    case 'number':
      return { t: 'f64' };
    case 'bool':
      return { t: 'bool' };
    case 'array':
      return { t: 'vec', of: valueType(ir.items, `${context}Item`, module) };
    case 'tuple':
      return {
        t: 'tuple',
        items: ir.items.map((item, index) =>
          valueType(
            item,
            ir.items.length > 1 ? `${context}Item${index}` : `${context}Item`,
            module,
          ),
        ),
      };
    case 'map':
      return { t: 'map', of: valueType(ir.value, `${context}Value`, module) };
    case 'freeobject':
      return { t: 'object' };
    case 'object':
      return declareStruct(module.claim(context, 'struct'), ir, module, null);
    case 'union':
      return declareUnion(module.claim(context, 'union'), ir, module, null);
    default:
      throw new Error(`unknown IR kind ${ir.k}`);
  }
}

/** Whether a reference points at a component whose Rust item already is an Option (a nullable component). */
const refIsNullable = (ir) => ir.k === 'ref' && !!deref(ir).nullable;

/** A type in a position without optionality (array items, map values, tuple items): nullable values are Options. */
function valueType(ir, context, module) {
  const base = typeRef(strip(ir), context, module);
  if (ir.nullable && base.t !== 'value' && !refIsNullable(strip(ir))) return { t: 'opt', of: base };
  return base;
}

const named = (module, name) => ({ t: 'named', mod: module.path, name });

function declareEnum(name, ir, module, doc) {
  const values = ir.consts;
  if (ir.open) {
    const used = new Set(['KNOWN']);
    const consts = values.map((value) => {
      let base = screaming(String(value)) || 'EMPTY';
      if (/^[0-9]/.test(base)) base = `N${base}`;
      let candidate = base;
      for (let suffix = 2; used.has(candidate); suffix++) candidate = `${base}_${suffix}`;
      used.add(candidate);
      return { ident: candidate, value };
    });
    addDecl(module, { kind: 'open', name, doc, consts });
  } else {
    const used = new Set(['Self']);
    const variants = values.map((value) => {
      let base = pascal(String(value)) || 'Empty';
      let candidate = base;
      for (let suffix = 2; used.has(candidate); suffix++) candidate = `${base}${suffix}`;
      used.add(candidate);
      return { ident: candidate, value };
    });
    addDecl(module, { kind: 'enum', name, doc, variants });
  }
  return named(module, name);
}

function fieldsOf(ir, structName, module, skip) {
  const used = new Set();
  const fields = [];
  for (const prop of ir.props) {
    if (skip && prop.name === skip) continue;
    let base = snake(prop.name) || 'member';
    if (/^[0-9]/.test(base)) base = `n_${base}`;
    let ident = rustIdent(base);
    for (let suffix = 2; used.has(ident); suffix++) ident = rustIdent(`${base}_${suffix}`);
    used.add(ident);
    const context = `${structName}${pascal(prop.name) || 'Member'}`;
    const stripped = strip(prop.ir);
    const tref = typeRef(stripped, context, module);
    let mode;
    if (tref.t === 'value') mode = 'present';
    else if (refIsNullable(stripped)) mode = prop.required ? 'required' : 'optional-nullable';
    else if (prop.ir.nullable) mode = prop.required ? 'nullable' : 'optional-nullable';
    else mode = prop.required ? 'required' : 'optional';
    fields.push({ ident, json: prop.name, tref, mode, doc: prop.description, ir: prop.ir });
  }
  let extra = null;
  if (ir.extra) {
    let ident = 'extra';
    for (let suffix = 2; used.has(ident); suffix++) ident = `extra_${suffix}`;
    const value = ir.extra.k === 'any' ? null : valueType(ir.extra, `${structName}Extra`, module);
    extra = { ident, tref: value ? { t: 'map', of: value } : { t: 'object' } };
  }
  return { fields, extra };
}

function declareStruct(name, ir, module, doc, skip) {
  const decl = addDecl(module, { kind: 'struct', name, doc, fields: [], extra: null });
  Object.assign(decl, fieldsOf(ir, name, module, skip));
  return named(module, name);
}

/** Every variant an inline object with a required single string constant member of the same name, all distinct. */
function discriminator(variants) {
  if (!variants.every((variant) => variant.k === 'object')) return null;
  const candidates = variants[0].props.filter((prop) => prop.required).map((prop) => prop.name);
  for (const member of candidates) {
    const values = [];
    let ok = true;
    for (const variant of variants) {
      const prop = variant.props.find((item) => item.name === member);
      const ir = prop && prop.required ? deref(prop.ir) : null;
      if (!ir || ir.k !== 'string' || ir.open || ir.nullable || ir.consts?.length !== 1) {
        ok = false;
        break;
      }
      values.push(ir.consts[0]);
    }
    if (ok && new Set(values).size === values.length) return { member, values };
  }
  return null;
}

function variantBaseName(variant, index, tag) {
  if (variant.k === 'ref') return variant.name;
  if (tag) return pascal(tag) || `Variant${index + 1}`;
  switch (variant.k) {
    case 'string':
      return 'String';
    case 'number':
      return 'Number';
    case 'bool':
      return 'Bool';
    case 'array':
      return 'Array';
    case 'tuple':
      return 'Tuple';
    case 'map':
      return 'Map';
    case 'freeobject':
      return 'Object';
    case 'object': {
      const disc = variant.props.find((prop) => {
        const ir = prop.required ? deref(prop.ir) : null;
        return ir && ir.k === 'string' && !ir.open && ir.consts?.length === 1;
      });
      if (disc) return pascal(deref(disc.ir).consts[0]) || `Variant${index + 1}`;
      return `Variant${index + 1}`;
    }
    default:
      return `Variant${index + 1}`;
  }
}

function declareUnion(name, ir, module, doc) {
  const disc = discriminator(ir.variants);
  const used = new Set(['Self']);
  const variantIdent = (base) => {
    let candidate = base;
    for (let suffix = 2; used.has(candidate); suffix++) candidate = `${base}${suffix}`;
    used.add(candidate);
    return candidate;
  };
  if (disc) {
    const decl = addDecl(module, { kind: 'tagged', name, doc, tag: disc.member, variants: [] });
    ir.variants.forEach((variant, index) => {
      const value = disc.values[index];
      const ident = variantIdent(variantBaseName(variant, index, value));
      const rest = variant.props.filter((prop) => prop.name !== disc.member);
      let tref = null;
      if (rest.length || variant.extra)
        tref = declareStruct(
          module.claim(`${name}${ident}`, 'struct'),
          variant,
          module,
          null,
          disc.member,
        );
      decl.variants.push({ ident, value, tref });
    });
  } else {
    const decl = addDecl(module, { kind: 'untagged', name, doc, variants: [] });
    ir.variants.forEach((variant, index) => {
      const ident = variantIdent(variantBaseName(variant, index, null));
      const tref = typeRef(variant, `${name}${ident}`, module);
      decl.variants.push({ ident, tref, shape: shapeOf(variant) });
    });
  }
  return named(module, name);
}

// Shapes for untagged unions.
const KIND = { null: 1, bool: 2, number: 4, string: 8, array: 16, object: 32, any: 63 };
function kindsOf(ir, seen = new Set()) {
  if (ir.k === 'ref') {
    if (seen.has(ir.name)) return KIND.any;
    seen.add(ir.name);
    const target = comp(ir.name);
    return kindsOf(target, seen) | (ir.nullable || target.nullable ? KIND.null : 0);
  }
  let kinds;
  switch (ir.k) {
    case 'any':
      return KIND.any;
    case 'null':
      kinds = KIND.null;
      break;
    case 'string':
    case 'number':
    case 'bool':
      kinds = KIND[ir.k === 'bool' ? 'bool' : ir.k];
      break;
    case 'array':
    case 'tuple':
      kinds = KIND.array;
      break;
    case 'map':
    case 'freeobject':
    case 'object':
      kinds = KIND.object;
      break;
    case 'union':
      kinds = ir.variants.reduce((all, variant) => all | kindsOf(variant, seen), 0);
      break;
    default:
      throw new Error(`unknown IR kind ${ir.k}`);
  }
  return kinds | (ir.nullable ? KIND.null : 0);
}

function constsOf(ir) {
  const target = deref(ir);
  if (
    (target.k === 'string' || target.k === 'number' || target.k === 'bool') &&
    target.consts &&
    !target.open
  ) {
    const consts = [...target.consts];
    if (target.nullable) consts.push(null);
    return consts;
  }
  return [];
}

function shapeOf(variant) {
  const target = deref(variant);
  const shape = { kinds: kindsOf(variant), consts: constsOf(variant), members: [], closed: false };
  if (target.k === 'object') {
    shape.members = target.props.map((prop) => ({
      name: prop.name,
      required: prop.required,
      kinds: kindsOf(prop.ir),
      consts: constsOf(prop.ir),
    }));
    shape.closed = target.extra === null;
  } else if (target.k === 'map' || target.k === 'freeobject') shape.closed = false;
  return shape;
}

/** Declares a top-level named item (component or operation type) for an IR node. */
function declareTop(name, ir, module, doc) {
  if (ir.nullable) {
    const inner = valueType(ir, `${name}Value`, module);
    addDecl(module, {
      kind: 'alias',
      name,
      doc,
      tref: inner.t === 'opt' ? inner : { t: 'opt', of: inner },
    });
    return;
  }
  switch (ir.k) {
    case 'object':
      declareStruct(name, ir, module, doc);
      return;
    case 'union':
      declareUnion(name, ir, module, doc);
      return;
    case 'string':
      if (ir.consts) {
        declareEnum(name, ir, module, doc);
        return;
      }
      break;
    default:
      break;
  }
  addDecl(module, { kind: 'alias', name, doc, tref: typeRef(ir, `${name}Item`, module) });
}

// --- components -----------------------------------------------------------------------------------------------------

for (const name of Object.keys(schemas)) {
  if (coreMapped.has(name)) continue;
  const doc = schemas[name].description;
  declareTop(name, comp(name), schemasModule, doc);
}

// --- operations -----------------------------------------------------------------------------------------------------

const groupModules = new Map();
function groupModule(group) {
  if (!groupModules.has(group)) {
    const ident = rustIdent(snake(group));
    const module = new Module(`api::${ident}`, `api/${snake(group)}.rs`, null);
    module.ident = ident;
    module.group = group;
    groupModules.set(group, module);
  }
  return groupModules.get(group);
}

const CALLS = {
  'credential, input': 'CredentialInput',
  input: 'Input',
  beginMfa: 'BeginMfa',
  confirmMfa: 'ConfirmMfa',
};

const operations = [];

function addOperation({ module, method, route, inputIR, outputIR, summary, call }) {
  const marker = module.claim(pascal(method) || 'Operation', 'operation');
  const inputName = module.claim(`${marker}Input`, 'input');
  const outputName = module.claim(`${marker}Output`, 'output');
  declareTop(inputName, inputIR, module, summary ? `Request body of \`${route.path}\`.` : null);
  declareTop(
    outputName,
    outputIR,
    module,
    summary ? `Result (\`data\`) of \`${route.path}\`.` : null,
  );
  const operation = { module, marker, inputName, outputName, route, summary, call };
  module.items.push(operation);
  operations.push(operation);
}

for (const route of routes.rpc) {
  const pathItem = openapi.paths[`/${route.path}`];
  if (!pathItem?.post)
    throw new Error(`routes.json route ${route.path} is missing from openapi.json`);
  const call = CALLS[route.call];
  if (!call)
    throw new Error(`routes.json route ${route.path}: unknown call ${JSON.stringify(route.call)}`);
  const post = pathItem.post;
  const body = post.requestBody?.content?.['application/json']?.schema;
  const envelope = post.responses?.['200']?.content?.['application/json']?.schema;
  const data = envelope?.properties?.data;
  if (!envelope || !data) throw new Error(`openapi.json ${route.path}: no 200 data schema`);
  addOperation({
    module: groupModule(route.group),
    method: route.method,
    route,
    inputIR: body ? norm(body) : { k: 'freeobject' },
    outputIR: norm(data),
    summary: post.summary,
    call,
  });
}
for (const path of Object.keys(openapi.paths))
  if (!routes.rpc.some((route) => `/${route.path}` === path))
    throw new Error(`openapi.json path ${path} is not an RPC route of routes.json`);

