const sortedJSON = (value) =>
  JSON.stringify(value, (key, item) =>
    item && typeof item === 'object' && !Array.isArray(item)
      ? Object.fromEntries(Object.entries(item).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)))
      : item,
  );

const specialModule = new Module('api::operations', 'api/operations.rs', null);
specialModule.ident = 'operations';
specialModule.group = null;
for (const [path, special] of Object.entries(SPECIAL)) {
  const declared = routes.special.find((item) => item.path === path);
  if (!declared) throw new Error(`routes.json has no special route ${path}`);
  if (declared.calls !== special.calls || sortedJSON(declared.body) !== sortedJSON(special.body))
    throw new Error(`routes.json special route ${path} changed; update SPECIAL in ${GENERATOR}`);
  addOperation({
    module: specialModule,
    method: path,
    route: {
      path,
      group: path,
      method: path,
      credential: declared.credential,
      tenantBound: false,
      setsSessionCookie: false,
      readsDeviceCookie: false,
    },
    inputIR: norm(special.input),
    outputIR: norm(special.output),
    summary: special.summary,
    call: 'Special',
  });
}
if (routes.special.some((item) => !SPECIAL[item.path] && !item.path.startsWith('plugins/')))
  throw new Error(`routes.json has special routes ${GENERATOR} does not know`);

// --- boxing and aliases ---------------------------------------------------------------------------------------------

/** Named references in a TypeRef: `direct` ones are stored inline (not behind a Vec or a map). */
function refsOf(tref, direct, out) {
  switch (tref.t) {
    case 'named':
      if (!tref.core) out.push({ key: keyOf(tref.mod, tref.name), direct });
      break;
    case 'vec':
    case 'map':
      refsOf(tref.of, false, out);
      break;
    case 'opt':
      refsOf(tref.of, direct, out);
      break;
    case 'tuple':
      tref.items.forEach((item) => refsOf(item, direct, out));
      break;
    default:
      break;
  }
  return out;
}

function declRefs(decl) {
  const out = [];
  switch (decl.kind) {
    case 'struct':
      decl.fields.forEach((field) => refsOf(field.tref, true, out));
      if (decl.extra) refsOf(decl.extra.tref, false, out);
      break;
    case 'tagged':
    case 'untagged':
      decl.variants.forEach((variant) => variant.tref && refsOf(variant.tref, true, out));
      break;
    case 'alias':
      refsOf(decl.tref, true, out);
      break;
    default:
      break;
  }
  return out;
}

function sccs(edgesOf) {
  // Tarjan's algorithm over declsByKey (iterative order: declaration order), returns key → component id.
  const index = new Map();
  const low = new Map();
  const onStack = new Set();
  const stack = [];
  const component = new Map();
  let counter = 0;
  let componentCount = 0;
  const strong = (start) => {
    const work = [{ key: start, edges: edgesOf(start), next: 0 }];
    index.set(start, counter);
    low.set(start, counter++);
    stack.push(start);
    onStack.add(start);
    while (work.length) {
      const frame = work[work.length - 1];
      if (frame.next < frame.edges.length) {
        const target = frame.edges[frame.next++];
        if (!declsByKey.has(target)) continue;
        if (!index.has(target)) {
          index.set(target, counter);
          low.set(target, counter++);
          stack.push(target);
          onStack.add(target);
          work.push({ key: target, edges: edgesOf(target), next: 0 });
        } else if (onStack.has(target))
          low.set(frame.key, Math.min(low.get(frame.key), index.get(target)));
      } else {
        work.pop();
        if (work.length) {
          const parent = work[work.length - 1].key;
          low.set(parent, Math.min(low.get(parent), low.get(frame.key)));
        }
        if (low.get(frame.key) === index.get(frame.key)) {
          let member;
          do {
            member = stack.pop();
            onStack.delete(member);
            component.set(member, componentCount);
          } while (member !== frame.key);
          componentCount++;
        }
      }
    }
  };
  for (const key of declsByKey.keys()) if (!index.has(key)) strong(key);
  return component;
}

// Type aliases cannot be recursive: an alias on any cycle becomes a transparent newtype.
{
  const all = sccs((key) => declRefs(declsByKey.get(key)).map((ref) => ref.key));
  const sizes = new Map();
  for (const id of all.values()) sizes.set(id, (sizes.get(id) ?? 0) + 1);
  for (const [key, decl] of declsByKey) {
    if (decl.kind !== 'alias') continue;
    const self = declRefs(decl).some((ref) => ref.key === key);
    if (sizes.get(all.get(key)) > 1 || self) decl.kind = 'newtype';
  }
}

// A reference stored inline to a type of the same strongly connected component (over inline references) is boxed.
const inlineComponents = sccs((key) =>
  declRefs(declsByKey.get(key))
    .filter((ref) => ref.direct)
    .map((ref) => ref.key),
);
const sameComponent = (fromKey, tref) =>
  tref.t === 'named' &&
  !tref.core &&
  inlineComponents.get(fromKey) === inlineComponents.get(keyOf(tref.mod, tref.name));

// Default can be derived when every required member's type has a default.
const defaultMemo = new Map();
function defaultable(tref) {
  switch (tref.t) {
    case 'value':
    case 'object':
    case 'string':
    case 'f64':
    case 'bool':
    case 'vec':
    case 'map':
    case 'opt':
      return true;
    case 'tuple':
      return tref.items.every(defaultable);
    case 'named':
      return !tref.core && declDefaultable(declsByKey.get(keyOf(tref.mod, tref.name)));
    default:
      return false;
  }
}
function declDefaultable(decl) {
  const key = keyOf(decl.mod, decl.name);
  if (defaultMemo.has(key)) return defaultMemo.get(key);
  defaultMemo.set(key, false);
  let result = false;
  if (decl.kind === 'struct')
    result = decl.fields.every((field) => field.mode !== 'required' || defaultable(field.tref));
  else if (decl.kind === 'open') result = true;
  else if (decl.kind === 'alias' || decl.kind === 'newtype') result = defaultable(decl.tref);
  defaultMemo.set(key, result);
  return result;
}

// --- rendering ------------------------------------------------------------------------------------------------------

function rustString(value) {
  let out = '"';
  for (const ch of value) {
    const code = ch.codePointAt(0);
    if (ch === '"') out += '\\"';
    else if (ch === '\\') out += '\\\\';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (code < 0x20 || code === 0x7f || (code >= 0x2028 && code <= 0x2029))
      out += `\\u{${code.toString(16)}}`;
    else out += ch;
  }
  return `${out}"`;
}

function rustNumber(value) {
  const text = String(value);
  if (!Number.isFinite(value)) throw new Error(`non-finite constant ${text}`);
  return /[.eE]/.test(text) ? text.replace('e+', 'e') : `${text}.0`;
}

function docLines(text, indent = '') {
  if (typeof text !== 'string' || !text.trim()) return '';
  let fenced = false;
  const lines = text
    .replace(/\r\n?/g, '\n')
    .trim()
    .split('\n')
    .map((line) => {
      let current = line.replace(/\s+$/, '');
      // A fence without a language is a Rust doctest to rustdoc; mark it as text.
      if (/^\s*```/.test(current)) {
        if (!fenced && /^\s*```\s*$/.test(current)) current = current.replace('```', '```text');
        fenced = !fenced;
      }
      return current ? `${indent}/// ${current}` : `${indent}///`;
    });
  return `${lines.join('\n')}\n`;
}

function typePath(tref, fromModule) {
  if (tref.t !== 'named') throw new Error('typePath of an unnamed type');
  if (tref.mod === fromModule) return tref.name;
  return `crate::${tref.mod}::${tref.name}`;
}

/** Rust type text; `fromKey` is the declaration it appears in (for boxing), `direct` false behind a Vec or map. */
function rustType(tref, fromModule, fromKey, direct = true) {
  switch (tref.t) {
    case 'value':
      return 'serde_json::Value';
    case 'object':
      return 'serde_json::Map<String, serde_json::Value>';
    case 'string':
      return 'String';
    case 'f64':
      return 'f64';
    case 'bool':
      return 'bool';
    case 'vec':
      return `Vec<${rustType(tref.of, fromModule, fromKey, false)}>`;
    case 'map':
      return `indexmap::IndexMap<String, ${rustType(tref.of, fromModule, fromKey, false)}>`;
    case 'opt':
      return `Option<${rustType(tref.of, fromModule, fromKey, direct)}>`;
    case 'tuple':
      return `(${tref.items.map((item) => rustType(item, fromModule, fromKey, direct)).join(', ')}${
        tref.items.length === 1 ? ',' : ''
      })`;
    case 'named': {
      const path = typePath(tref, fromModule);
      return direct && fromKey && sameComponent(fromKey, tref) ? `Box<${path}>` : path;
    }
    default:
      throw new Error(`unknown TypeRef ${tref.t}`);
  }
}

const LINTS = [
  'clippy::large_enum_variant',
  'clippy::enum_variant_names',
  'clippy::upper_case_acronyms',
  'clippy::type_complexity',
  'clippy::doc_lazy_continuation',
  'clippy::doc_overindented_list_items',
  'clippy::too_long_first_doc_paragraph',
  'non_camel_case_types',
];

function constText(value) {
  if (value === null) return 'Const::Null';
  if (typeof value === 'boolean') return `Const::Bool(${value})`;
  if (typeof value === 'number') return `Const::Number(${rustNumber(value)})`;
  return `Const::Str(${rustString(value)})`;
}

function kindText(kinds) {
  if (kinds === KIND.any) return 'kind::ANY';
  return Object.entries(KIND)
    .filter(([name, bit]) => name !== 'any' && kinds & bit)
    .map(([name]) => `kind::${name.toUpperCase()}`)
    .join(' | ');
}

function shapeText(shape) {
  const consts = `&[${shape.consts.map(constText).join(', ')}]`;
  const members = shape.members
    .map(
      (member) =>
        `Member::new(${rustString(member.name)}, ${member.required}, ${kindText(member.kinds)}, &[${member.consts
          .map(constText)
          .join(', ')}])`,
    )
    .join(', ');
  return `Shape::new(${kindText(shape.kinds)}, ${consts}, &[${members}], ${shape.closed})`;
}

function renderField(field, module, key) {
  const attrs = [];
  if (serdeCamel(field.ident) !== field.json) attrs.push(`rename = ${rustString(field.json)}`);
  const base = rustType(field.tref, module.path, key);
  let type;
  switch (field.mode) {
    case 'required':
      type = base;
      break;
    case 'nullable':
      type = `Option<${base}>`;
      break;
    case 'optional':
      type = `Option<${base}>`;
      attrs.push('default', 'skip_serializing_if = "Option::is_none"');
      break;
    case 'optional-nullable':
      type =
        field.tref.t === 'named' && refIsNullable(strip(field.ir))
          ? `Option<${base}>`
          : `Option<Option<${base}>>`;
      attrs.push(
        'default',
        'skip_serializing_if = "Option::is_none"',
        'with = "crate::runtime::nullable"',
      );
      break;
    case 'present':
      type = 'Option<serde_json::Value>';
      attrs.push(
        'default',
        'skip_serializing_if = "Option::is_none"',
        'with = "crate::runtime::present"',
      );
      break;
    default:
      throw new Error(`unknown field mode ${field.mode}`);
  }
  let out = docLines(field.doc, '    ');
  if (attrs.length) out += `    #[serde(${attrs.join(', ')})]\n`;
  out += `    pub ${field.ident}: ${type},\n`;
  return out;
}

const DERIVE = '#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]';
const DERIVE_DEFAULT =
  '#[derive(Debug, Clone, PartialEq, Default, serde::Serialize, serde::Deserialize)]';

function renderDecl(decl, module) {
  const key = keyOf(decl.mod, decl.name);
  let out = docLines(decl.doc);
  switch (decl.kind) {
    case 'struct': {
      out += `${declDefaultable(decl) ? DERIVE_DEFAULT : DERIVE}\n#[serde(rename_all = "camelCase")]\n`;
      out += `pub struct ${decl.name} {\n`;
      for (const field of decl.fields) out += renderField(field, module, key);
      if (decl.extra) {
        out += '    /// Members the schema does not declare.\n    #[serde(flatten)]\n';
        out += `    pub ${decl.extra.ident}: ${rustType(decl.extra.tref, module.path, key)},\n`;
      }
      out += '}\n';
      return out;
    }
    case 'enum':
      out = `string_enum! {\n${docLines(decl.doc, '    ')}    pub enum ${decl.name} {\n`;
      for (const variant of decl.variants)
        out += `        ${variant.ident} = ${rustString(variant.value)},\n`;
      return `${out}    }\n}\n`;
    case 'open':
      out = `open_enum! {\n${docLines(decl.doc, '    ')}    pub struct ${decl.name} {\n`;
      for (const constant of decl.consts)
        out += `        ${constant.ident} = ${rustString(constant.value)},\n`;
      return `${out}    }\n}\n`;
    case 'tagged': {
      out += `${DERIVE}\n#[serde(tag = ${rustString(decl.tag)})]\npub enum ${decl.name} {\n`;
      for (const variant of decl.variants) {
        out += `    #[serde(rename = ${rustString(variant.value)})]\n`;
        out += variant.tref
          ? `    ${variant.ident}(${rustType(variant.tref, module.path, key)}),\n`
          : `    ${variant.ident},\n`;
      }
      return `${out}}\n`;
    }
    case 'untagged': {
      out += '#[derive(Debug, Clone, PartialEq, serde::Serialize)]\n#[serde(untagged)]\n';
      out += `pub enum ${decl.name} {\n`;
      for (const variant of decl.variants)
        out += `    ${variant.ident}(${rustType(variant.tref, module.path, key)}),\n`;
      out += '}\n\n';
      out += `impl<'de> serde::Deserialize<'de> for ${decl.name} {\n`;
      out += `    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {\n`;
      let body = '';
      for (const variant of decl.variants) {
        const boxed = rustType(variant.tref, module.path, key).startsWith('Box<');
        const wrap = boxed
          ? `|value| serde_json::from_value(value).map(|inner| ${decl.name}::${variant.ident}(Box::new(inner)))`
          : `|value| serde_json::from_value(value).map(${decl.name}::${variant.ident})`;
        body += `            Variant { shape: ${shapeText(variant.shape)}, decode: ${wrap} },\n`;
      }
      const imports = ['kind', 'Const', 'Member'].filter((name) => body.includes(`${name}::`));
      out += `        use crate::runtime::{${[...imports, 'Shape', 'Variant'].join(', ')}};\n`;
      out += `        static VARIANTS: &[Variant<${decl.name}>] = &[\n${body}        ];\n`;
      out += `        crate::runtime::untagged(deserializer, ${rustString(decl.name)}, VARIANTS)\n    }\n}\n`;
      return out;
    }
    case 'alias':
      return `${out}pub type ${decl.name} = ${rustType(decl.tref, module.path, key, false)};\n`;
    case 'newtype': {
      const derive = declDefaultable(decl) ? DERIVE_DEFAULT : DERIVE;
      return `${out}${derive}\n#[serde(transparent)]\npub struct ${decl.name}(pub ${rustType(
        decl.tref,
        module.path,
        key,
      )});\n`;
    }
    default:
      throw new Error(`unknown declaration kind ${decl.kind}`);
  }
}

function moduleHeader(doc) {
  return `${HEADER}\n${doc}\n#![allow(${LINTS.join(', ')})]\n\n`;
}

function renderRoute(operation) {
  const { route, module } = operation;
  return [
    'crate::routes::Route {',
    `path: ${rustString(route.path)},`,
    `group: ${rustString(route.group)},`,
    `method: ${rustString(route.method)},`,
    `public: ${route.credential === 'none'},`,
    `call: crate::routes::Call::${operation.call},`,
    `tenant_bound: ${!!route.tenantBound},`,
    `sets_session_cookie: ${!!route.setsSessionCookie},`,
    `reads_device_cookie: ${!!route.readsDeviceCookie},`,
    `input: ${rustString(`${module.path}::${operation.inputName}`)},`,
    `output: ${rustString(`${module.path}::${operation.outputName}`)},`,
    '}',
  ].join(' ');
}

function renderModule(module) {
  let out = '';
  for (const operation of module.items) {
    out += docLines(operation.summary);
    out += `///\n/// \`POST {basePath}/${operation.route.path}\`: input [\`${operation.inputName}\`], output [\`${operation.outputName}\`].\n`;
    out += '#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Hash)]\n';
    out += `pub struct ${operation.marker};\n\n`;
    out += `impl crate::routes::Operation for ${operation.marker} {\n`;
    out += `    type Input = ${operation.inputName};\n    type Output = ${operation.outputName};\n`;
    out += `    const ROUTE: crate::routes::Route = ${renderRoute(operation)};\n}\n\n`;
  }
  for (const decl of module.decls) out += `${renderDecl(decl, module)}\n`;
  return out;
}

// --- files ----------------------------------------------------------------------------------------------------------

const files = new Map(); // path under src/ → text

{
  const mapped = [...coreMapped];
  let out = moduleHeader(
    [
      '//! One item per component schema of the OpenAPI document (`components.schemas`), in document order. Schemas',
      '//! better-iam-core already declares are re-exported from it.',
    ].join('\n'),
  );
  out += `pub use better_iam_core::{${mapped.join(', ')}};\n\n`;
  out += `/// The component schemas that are better-iam-core types.\npub const CORE_SCHEMAS: &[&str] = &[${mapped
    .map(rustString)
    .join(', ')}];\n\n`;
  out += renderModule(schemasModule);
  files.set('schemas.rs', out);
}

const modules = [
  ...[...groupModules.values()].sort((a, b) => (a.ident < b.ident ? -1 : 1)),
  specialModule,
];
{
  let out = moduleHeader(
    [
      '//! The request and result types of every API route, one module per API group (`POST {basePath}/{group}/{method}`),',
      '//! plus `operations` for `authorize`, `authorizeMany` and `listAccessible`.',
    ].join('\n'),
  );
  for (const module of modules) {
    const what = module.group
      ? `The \`${module.group}\` API group.`
      : 'The `authorize`, `authorizeMany` and `listAccessible` routes.';
    out += `/// ${what}\npub mod ${module.ident};\n`;
  }
  files.set('api/mod.rs', out);
  for (const module of modules) {
    const what = module.group
      ? `//! The \`${module.group}\` API group: request and result types and one marker per route.`
      : '//! The `authorize`, `authorizeMany` and `listAccessible` routes (packages/server/src/operations.ts).';
    files.set(module.file, moduleHeader(what) + renderModule(module));
  }
}

{
  const all = operations;
  let out = moduleHeader(
    [
      '//! The route table of the HTTP API (spec/api/routes.json): every `POST {basePath}/{path}` route with how the',
      '//! router calls it and its typed request and result.',
    ].join('\n'),
  );
  out += `/// The default base path of the HTTP API.\npub const BASE_PATH: &str = ${rustString(routes.basePath)};\n\n`;
  out +=
    '/// Plugin endpoints are routed as `plugins/{pluginId}/{endpointPath...}` (not listed in [`ROUTES`]).\n' +
    'pub const PLUGIN_ROUTE_PREFIX: &str = "plugins/";\n\n';
  out += `/// How the router invokes a route's method.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Call {
    /// \`(credential, body)\`: authenticated routes.
    CredentialInput,
    /// \`(body)\`: public routes.
    Input,
    /// \`auth/beginMfa\`: \`{ tenantId, challenge }\` when \`body.challenge\` is a string, else the request credential.
    BeginMfa,
    /// \`auth/confirmMfa\`: the credential is \`body.credential\` for a challenge, else the request credential.
    ConfirmMfa,
    /// \`authorize\`, \`authorizeMany\`, \`listAccessible\`: dispatched before the group routes, with the request
    /// credential.
    Special,
}

/// One row of the route table.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct Route {
    /// The path below the base path (\`roles/create\`).
    pub path: &'static str,
    /// The API group (the path itself for the special routes).
    pub group: &'static str,
    /// The method of the group (the path itself for the special routes).
    pub method: &'static str,
    /// Whether the route is called without a credential.
    pub public: bool,
    pub call: Call,
    /// Public routes whose tenant comes from the request host (\`tenantBoundPublicMethods\`).
    pub tenant_bound: bool,
    /// Whether a successful answer sets the session cookie.
    pub sets_session_cookie: bool,
    /// Whether the route reads the trusted-device cookie.
    pub reads_device_cookie: bool,
    /// The Rust path of the input type below the crate (\`api::roles::CreateInput\`).
    pub input: &'static str,
    /// The Rust path of the output type below the crate.
    pub output: &'static str,
}

/// A route with its typed request body (\`Input\`) and result (\`Output\`, the \`data\` of the answer).
pub trait Operation {
    type Input: serde::Serialize + serde::de::DeserializeOwned + std::fmt::Debug + Clone + Send + Sync + 'static;
    type Output: serde::Serialize + serde::de::DeserializeOwned + std::fmt::Debug + Clone + Send + Sync + 'static;
    const ROUTE: Route;
}

/// Something done with the [\`Operation\`] of a route path, see [\`visit\`].
pub trait RouteVisitor {
    type Output;
    fn visit<O: Operation>(self) -> Self::Output;
}

`;
  out += `/// Every route, the special routes first (the order the router tries them), then the group routes in path order.\npub static ROUTES: &[Route] = &[\n`;
  const ordered = [
    ...all.filter((op) => op.call === 'Special'),
    ...all.filter((op) => op.call !== 'Special'),
  ];
  for (const operation of ordered)
    out += `    <crate::${operation.module.path}::${operation.marker} as Operation>::ROUTE,\n`;
  out += '];\n\n';
  out +=
    "/// The route of a path below the base path.\npub fn lookup(path: &str) -> Option<&'static Route> {\n";
  out += '    let index = match path {\n';
  ordered.forEach((operation, index) => {
    out += `        ${rustString(operation.route.path)} => ${index},\n`;
  });
  out += '        _ => return None,\n    };\n    Some(&ROUTES[index])\n}\n\n';
  out += '/// Calls `visitor.visit::<O>()` with the operation of a path below the base path.\n';
  out +=
    'pub fn visit<V: RouteVisitor>(path: &str, visitor: V) -> Option<V::Output> {\n    Some(match path {\n';
  for (const operation of ordered)
    out += `        ${rustString(operation.route.path)} => visitor.visit::<crate::${operation.module.path}::${operation.marker}>(),\n`;
  out += '        _ => return None,\n    })\n}\n';
  files.set('routes.rs', out);
}

// --- write and format -----------------------------------------------------------------------------------------------

function findRustfmt() {
  const exe = process.platform === 'win32' ? 'rustfmt.exe' : 'rustfmt';
  const candidates = [];
  if (process.env.RUSTFMT) candidates.push(process.env.RUSTFMT);
  candidates.push('rustfmt');
  const cargoHome = process.env.CARGO_HOME || join(homedir(), '.cargo');
  candidates.push(join(cargoHome, 'bin', exe));
  for (const candidate of candidates) {
    const probe = spawnSync(candidate, ['--version'], { encoding: 'utf8' });
    if (probe.status === 0) return candidate;
  }
  throw new Error(
    'rustfmt was not found (PATH, $RUSTFMT or ~/.cargo/bin); install it with `rustup component add rustfmt`',
  );
}

const srcDir = join(outDir, 'src');
mkdirSync(join(srcDir, 'api'), { recursive: true });
// Generated files that are not produced any more.
for (const name of readdirSync(join(srcDir, 'api'))) {
  if (name.endsWith('.rs') && !files.has(`api/${name}`)) rmSync(join(srcDir, 'api', name));
}
const written = [];
for (const [path, text] of files) {
  const target = join(srcDir, path);
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, text.replace(/\n{3,}/g, '\n\n').replace(/\n*$/, '\n'));
  written.push(target);
}
const rustfmt = findRustfmt();
for (let index = 0; index < written.length; index += 64) {
  const chunk = written.slice(index, index + 64);
  const result = spawnSync(rustfmt, ['--edition', '2024', ...chunk], { encoding: 'utf8' });
  if (result.status !== 0) {
    process.stderr.write(result.stderr || result.stdout || '');
    throw new Error('rustfmt failed on the generated files');
  }
}
// rustfmt keeps CRLF out of the files it writes on every platform only when told; normalize to LF.
for (const target of written) {
  const text = readFileSync(target, 'utf8');
  if (text.includes('\r\n')) writeFileSync(target, text.replace(/\r\n/g, '\n'));
}

if (coreWithoutSerde.length)
  warnings.push(
    `better-iam-core declares ${coreWithoutSerde.join(', ')} without a serde form; generated in schemas instead`,
  );
for (const warning of new Set(warnings)) console.warn(`warning: ${warning}`);
console.log(
  `${GENERATOR}: ${files.size} files, ${Object.keys(schemas).length} schemas (${coreMapped.size} from better-iam-core), ${operations.length} routes → ${srcDir}`,
);
if (!existsSync(join(srcDir, 'lib.rs')))
  console.warn(`warning: ${join(srcDir, 'lib.rs')} does not exist`);
